package project.init.account.domain.entity;import jakarta.persistence.CascadeType;import jakarta.persistence.Column;import jakarta.persistence.Entity;import jakarta.persistence.FetchType;import jakarta.persistence.Id;import jakarta.persistence.JoinColumn;import jakarta.persistence.JoinTable;import jakarta.persistence.ManyToMany;import jakarta.persistence.OneToOne;import jakarta.persistence.PrePersist;import jakarta.persistence.PreUpdate;import jakarta.persistence.Table;import lombok.Getter;import lombok.Setter;import org.hibernate.annotations.Fetch;import org.hibernate.annotations.FetchMode;import project.init.framework.utils.DateTimeUtils;import java.sql.Timestamp;import java.time.Instant;import java.util.List;@Getter@Setter@Entity@Table(name = "account")public class Account {    @Id    @Column(name = "account_code", length = 50, nullable = false)    private String accountCode;    @Column(name = "password_hash", nullable = false, columnDefinition = "TEXT")    private String passwordHash;    @Column(name = "account_status", length = 10, nullable = false)    private String accountStatus = "ACTIVE";    @Column(name = "created_at", updatable = false)    private Instant createdAt;    @Column(name = "updated_at")    private Timestamp updatedAt;    @ManyToMany(fetch = FetchType.EAGER, cascade = CascadeType.MERGE)    @JoinTable(            name = "account_role",            joinColumns = @JoinColumn(name = "account_code"),            inverseJoinColumns = @JoinColumn(name = "role_id")    )    @Fetch(FetchMode.SUBSELECT)    private List<Role> roles;    @OneToOne(fetch = FetchType.LAZY, cascade = CascadeType.ALL)    @JoinColumn(name = "account_code")    private AccountInfo accountInfo;    @PrePersist    protected void onCreate() {        createdAt = DateTimeUtils.getCurrentTimeUTC();        updatedAt = DateTimeUtils.getCurrentTimestamp();    }    @PreUpdate    protected void onUpdate() {        updatedAt = DateTimeUtils.getCurrentTimestamp                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           ();    }}// -----------------------------------------------------------------------------/* @OneToOne:               1-1 * fetch = FetchType:    • .LAZY:                Chỉ load khi gọi getter → tối ưu hiệu năng    • .EAGER:               Luôn load entity liên kết ngay lập tức khi truy vấn entity chính (kể cả khi chưa cần dùng) * cascade = CascadeType:   Khi thao tác trên entity cha, có tự áp dụng cho entity liên kết không?	•	.ALL:               áp dụng toàn bộ các thao tác:	•	.PERSIST:           Lưu mới	•	.MERGE:             Cập nhật	•	.REMOVE:            Xoá	•	.REFRESH:           Đồng bộ lại từ DB	•	.DETACH:            Gỡ khỏi context quản lý * @Fetch * FetchMode.SUBSELECT*/